JS = '<script id="tamiyouz-join-us-reference-exact-v3-js">\n(function(){\n  var toggle=document.querySelector(\'.ref3-menu-toggle\'),nav=document.getElementById(\'ref3Nav\');\n  if(toggle&&nav){toggle.addEventListener(\'click\',function(){var open=nav.classList.toggle(\'open\');toggle.setAttribute(\'aria-expanded\',open?\'true\':\'false\');});}\n  var items=document.querySelectorAll(\'.ref3-reveal\');\n  if(window.matchMedia&&window.matchMedia(\'(prefers-reduced-motion: reduce)\').matches){items.forEach(function(el){el.classList.add(\'is-visible\');});return;}\n  if(\'IntersectionObserver\'in window){var io=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add(\'is-visible\');io.unobserve(e.target);}});},{threshold:.12});items.forEach(function(el){io.observe(el);});}else{items.forEach(function(el){el.classList.add(\'is-visible\');});}\n})();\n</script>'

HERO_B64 = ""
CULTURE_B64 = ""
CTA_B64 = ""

def one_sub(pattern, repl, text, label):
    out, n = re.subn(pattern, lambda m: repl, text, count=1, flags=re.S)
    if n != 1:
        raise SystemExit(f"{label}: expected exactly one match, found {n}")
    return out

def write_asset(path: Path, data_b64: str):
    raw = base64.b64decode(data_b64.encode("ascii"), validate=True)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(raw)
    return hashlib.sha256(raw).hexdigest(), len(raw)

def transform(source: str):
    for marker in REQUIRED:
        if marker not in source:
            raise SystemExit(f"Required source marker missing: {marker}")
    if PATCH_MARKER in source:
        raise SystemExit("V3 exact-reference marker already present.")

    out = source
    out = one_sub(r'<header class="site-header".*?</header>', HEADER, out, "header")
    out = one_sub(r'<main class="lux-page".*?</main>', MAIN, out, "main")
    out = one_sub(r'<footer class="site-footer".*?</footer>', FOOTER, out, "footer")

    if "</head>" not in out or "</body>" not in out:
        raise SystemExit("Missing head/body anchor")

    out = out.replace("</head>", CSS + "\n</head>", 1)
    out = out.replace("</body>", JS + "\n</body>", 1)

    guards = {
        "marker_once": out.count(PATCH_MARKER) == 1,
        "visible_h1_once": out.count('<h1 id="join-us-title">') == 1,
        "careers_iframe_once": out.count('id="careersFrame"') == 1,
        "careers_url": "https://careers.tamiyouzplaform.com/" in out,
        "rakan": "https://careers.tamiyouzplaform.com/api/v1/rakan/chat" in out,
        "form_submission": "e.data.type === 'formSubmission'" in out,
        "notify_hook": "fetch('/join-us/notify.php'" in out,
        "force_template": "TAM_JOIN_US_WORDPRESS_FORCE_V1" in out,
        "v1": "TAM_JOIN_US_LUXURY_V1" in out,
        "v2": "TAM_JOIN_US_LUXURY_V2_FIDELITY" in out,
        "collection_schema": '"@type":"CollectionPage"' in out,
        "no_jobposting": '"@type":"JobPosting"' not in out and '"@type": "JobPosting"' not in out,
        "reduced_motion": "prefers-reduced-motion:reduce" in out,
        "header_rebuilt": 'class="ref3-header"' in out,
        "footer_rebuilt": 'class="ref3-footer"' in out,
        "target_sections": all(x in out for x in ["ref3-application","ref3-stats","ref3-why","ref3-roles","ref3-testimonials","ref3-final-cta"]),
    }
    failed = [k for k, v in guards.items() if not v]
    if failed:
        raise SystemExit("Post-transform guard failed: " + ", ".join(failed))
    return out, guards

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--source", required=True)
    ap.add_argument("--output", required=True)
    ap.add_argument("--asset-dir", required=True)
    ap.add_argument("--manifest")
    args = ap.parse_args()

    source_path = Path(args.source)
    output_path = Path(args.output)
    asset_dir = Path(args.asset_dir)

    source = source_path.read_text(encoding="utf-8")
    result, guards = transform(source)
    output_path.write_text(result, encoding="utf-8")

    hero_sha, hero_bytes = write_asset(asset_dir / "hero-reference.webp", HERO_B64)
    culture_sha, culture_bytes = write_asset(asset_dir / "culture-reference.webp", CULTURE_B64)
    cta_sha, cta_bytes = write_asset(asset_dir / "cta-reference.webp", CTA_B64)

    manifest = {
        "patch": PATCH_ID,
        "patch_marker": PATCH_MARKER,
        "source_sha256": hashlib.sha256(source.encode("utf-8")).hexdigest(),
        "output_sha256": hashlib.sha256(result.encode("utf-8")).hexdigest(),
        "files_changed": [
            "themes/thegem-elementor/page-join-us.php",
            "themes/thegem-elementor/assets/join-us/reference-v3/hero-reference.webp",
            "themes/thegem-elementor/assets/join-us/reference-v3/culture-reference.webp",
            "themes/thegem-elementor/assets/join-us/reference-v3/cta-reference.webp",
        ],
        "assets": {
            "hero-reference.webp": {"sha256": hero_sha, "bytes": hero_bytes},
            "culture-reference.webp": {"sha256": culture_sha, "bytes": culture_bytes},
            "cta-reference.webp": {"sha256": cta_sha, "bytes": cta_bytes},
        },
        "reference_strategy": "semantic HTML/CSS for all structure plus three small local art-direction crops from the approved reference",
        "integrations_preserved": True,
        "seo_schema_preserved": True,
        "git_mutations_by_patch_runner": False,
        "guards": guards,
    }
    if args.manifest:
        Path(args.manifest).write_text(json.dumps(manifest, indent=2, ensure_ascii=False), encoding="utf-8")
    print(json.dumps(manifest, indent=2, ensure_ascii=False))

if __name__ == "__main__":
    main()
